        self._state = state
        self._scheduler_interval = scheduler_interval
        self._scheduler_max_runs = scheduler_max_runs
        self._scheduled_tasks = {}
        self._lock = threading.Lock()
        self._stop_event = threading.Event()
        self._thread = threading.Thread(target=self._loop)
        self._thread.start()

    def _loop(self):
        while not self._stop_event.wait(self._scheduler_interval):
            with self._lock:
                self._run_once()

    def _run_once(self):
        try:
            if self._scheduler_max_runs is not None:
                for _ in range(self._scheduler_max_runs):
                    self._schedule_once()
